import { type RequestResult, SynapseEnhancedError, ErrorCode } from "./http.ts";
import { getErrorCodeFromStatus, normalizeErrorCode } from "./error-codes.ts";
import { isSynapseRust, useWrappedResponse } from "../constants/api.ts";

export interface ApiResponse<T> {
    status: string;
    data?: T;
    error?: string;
    details?: Record<string, unknown>;
}

/**
 * Enhanced response handler that supports both wrapped and bare response formats
 *
 * Wrapped format (standard): { status: "ok", data: {...} }
 * Bare format (Synapse Rust): { items: [...] } or { result: ... } or just the data directly
 *
 * @param response - The HTTP response
 * @param defaultError - Default error message if response.error is missing
 * @param allowBareResponse - Whether to accept bare responses (no status field). Default: auto-detect based on backend profile
 */
export function handleApiResponse<T>(
    response: RequestResult<{ status?: string | number; data?: T; error?: string } & Record<string, unknown>>,
    defaultError: string = "Request failed",
    allowBareResponse?: boolean,
): T {
    const responseData = response.data;
    const hasStatusField = "status" in responseData && responseData.status !== undefined;

    // Auto-detect if we should allow bare responses based on backend profile
    const shouldAllowBare = allowBareResponse ?? (!useWrappedResponse() || isSynapseRust());

    // Handle bare response (no status field) - common in Synapse Rust
    if (!hasStatusField) {
        if (shouldAllowBare) {
            // Check if response has data-like fields (items, result, or direct data)
            if ("data" in responseData && responseData.data !== undefined) {
                return responseData.data as T;
            }
            if ("items" in responseData && responseData.items !== undefined) {
                return responseData.items as unknown as T;
            }
            if ("result" in responseData && responseData.result !== undefined) {
                return responseData.result as unknown as T;
            }
            // If response has error field but no status, treat as error
            if ("error" in responseData && responseData.error !== undefined) {
                throw new SynapseEnhancedError(
                    String(responseData.error),
                    ErrorCode.UNKNOWN,
                    undefined,
                    response.status,
                );
            }
            // Treat the whole response as data
            return responseData as unknown as T;
        }
        // Status field required but missing
        throw new SynapseEnhancedError(
            `Response missing status field: ${JSON.stringify(responseData)}`,
            ErrorCode.INVALID_PARAM,
            undefined,
            response.status,
        );
    }

    // Handle wrapped response with status field
    const status = String(responseData.status);
    const isOk = status === "ok" || status === "success" || status === "200" || status === "true";

    if (isOk) {
        if (responseData.data === undefined) {
            // Some successful responses might not have data, return empty object
            return {} as T;
        }
        return responseData.data;
    }

    throw new SynapseEnhancedError(
        responseData.error || defaultError,
        Number.isNaN(Number(status)) ? normalizeErrorCode(status) : getErrorCodeFromStatus(Number(status)),
    );
}

export interface PaginatedResponse<T> {
    items: T[];
    pagination: {
        page: number;
        page_size: number;
        total: number;
        has_more: boolean;
    };
}

export interface RawBackendResponse {
    status: string;
    success?: boolean;
    data?: unknown;
    result?: unknown;
    items?: unknown[];
    error?: string;
    details?: Record<string, unknown>;
    pagination?: {
        page?: number;
        page_size?: number;
        total?: number;
        has_more?: boolean;
        cursor?: string;
    };
}

export function formatApiResponse<T>(response: RawBackendResponse): ApiResponse<T> {
    let data: T | undefined;

    if (response.data !== undefined) {
        data = response.data as T;
    } else if (response.result !== undefined) {
        data = response.result as T;
    } else if (response.items !== undefined) {
        data = response.items as unknown as T;
    }

    return {
        status: response.status,
        data,
        error: response.error,
        details: response.details,
    };
}

export function formatPaginatedResponse<T>(
    response: RawBackendResponse,
    page: number,
    pageSize: number,
): PaginatedResponse<T> {
    const items = (response.data as T[]) || (response.items as T[]) || [];
    const total = response.pagination?.total ?? items.length;
    const hasMore = response.pagination?.has_more ?? response.pagination?.cursor !== undefined;

    return {
        items,
        pagination: {
            page,
            page_size: pageSize,
            total,
            has_more: hasMore,
        },
    };
}

export function isSuccessStatus(status: string): boolean {
    return status === "ok" || status === "success" || status === "200" || status === "true";
}

export function getErrorMessage(error: string | undefined, defaultMessage: string): string {
    return error || defaultMessage;
}

export function extractDataFromResponse<T>(response: RawBackendResponse): T | null {
    if (!isSuccessStatus(response.status)) {
        return null;
    }

    if (response.data !== undefined) {
        return response.data as T;
    }

    if (response.result !== undefined) {
        return response.result as T;
    }

    if (response.items !== undefined) {
        return response.items as unknown as T;
    }

    return null;
}

export function convertBooleanValue(value: unknown): boolean {
    if (typeof value === "boolean") {
        return value;
    }
    if (typeof value === "string") {
        return value === "yes" || value === "true" || value === "1" || value === "ok";
    }
    if (typeof value === "number") {
        return value !== 0;
    }
    return false;
}

export function convertNumberValue(value: unknown, defaultValue: number = 0): number {
    if (typeof value === "number") {
        return value;
    }
    if (typeof value === "string") {
        const parsed = parseFloat(value);
        return isNaN(parsed) ? defaultValue : parsed;
    }
    return defaultValue;
}

export function convertDateValue(value: unknown): Date {
    if (value instanceof Date) {
        return value;
    }
    if (typeof value === "string") {
        return new Date(value);
    }
    if (typeof value === "number") {
        return new Date(value);
    }
    return new Date();
}

export function normalizePaginationParams(page?: number, limit?: number): { page: number; page_size: number } {
    return {
        page: page ?? 1,
        page_size: Math.min(Math.max(1, limit ?? 20), 100),
    };
}

export function parsePaginationFromResponse(response: RawBackendResponse): {
    page?: number;
    page_size?: number;
    total?: number;
    cursor?: string;
    has_more?: boolean;
} {
    return {
        page: response.pagination?.page,
        page_size: response.pagination?.page_size,
        total: response.pagination?.total,
        cursor: response.pagination?.cursor,
        has_more: response.pagination?.has_more,
    };
}

export interface BackendDataResponse<T> {
    status: string | number;
    data?: {
        items?: T[];
        total?: number;
        page?: number;
        limit?: number;
    };
    error?: string;
}

export function extractItemsFromDataResponse<T>(
    response: RequestResult<BackendDataResponse<T>>,
    fallbackItems: T[] = [],
): { items: T[]; total: number; page: number; limit: number } {
    const responseData = response.data;
    const statusOk = responseData.status === "ok" || responseData.status === 200;
    if (!statusOk || !responseData.data) {
        return {
            items: fallbackItems,
            total: 0,
            page: 1,
            limit: 20,
        };
    }

    return {
        items: responseData.data.items || fallbackItems,
        total: responseData.data.total || 0,
        page: responseData.data.page || 1,
        limit: responseData.data.limit || 20,
    };
}

export function formatBackendDataResponse<T>(
    response: BackendDataResponse<T>,
    dataField:
        | "friends"
        | "requests"
        | "users"
        | "rooms"
        | "messages"
        | "categories"
        | "blocked_users"
        | "sessions"
        | "logs"
        | "events"
        | "admins",
): { status: string; [key: string]: unknown } {
    const statusOk = response.status === "ok" || response.status === 200;
    if (!statusOk) {
        return {
            status: String(response.status),
            error: response.error,
        };
    }

    if (response.data?.items) {
        return {
            status: "ok",
            [dataField]: response.data.items,
            total: response.data.total,
            page: response.data.page,
            limit: response.data.limit,
        };
    }

    return {
        status: "ok",
        [dataField]: [],
        total: 0,
        page: 1,
        limit: 20,
    };
}
